begin;
do $$begin if current_database()<>'factory_lean_quality_local' or inet_server_addr()<>'127.0.0.1'::inet or inet_server_port()<>55491 then raise exception 'Disposable Phase4A localhost only';end if;end$$;
truncate late_test.checks;
do $$declare x jsonb;y jsonb;w jsonb;p jsonb;r jsonb;replay jsonb;h private.manufactured_outputs;
 f uuid;origin uuid;entry uuid;k uuid:=gen_random_uuid();bad jsonb;before_rows bigint;package uuid;begin
 x:=output4_test.context('All Scrap');f:=(x->>'factory')::uuid;origin:=(x->>'item')::uuid;
 w:=output4_test.decision(x,'COMPLETE',10);y:=output4_test.start(x,w);
 p:=output2_test.payload(y,0)||jsonb_build_object('input_lot',x->>'lot','input_quantity',10,'discarded_quantity',10,'scrap_kg',0.75,'notes','Measured scale mass 0.75 KG; whole recovery discarded');
 perform late_test.ok((select quantity_available=10 and warehouse_quantity=0 from public.unfinished_lots where id=(x->>'lot')::uuid),'issue moved actual ten to floor before recording');
 select count(*) into before_rows from public.production_entries where factory_id=f;
 foreach bad in array array['null'::jsonb,'0'::jsonb,'-1'::jsonb,'"NaN"'::jsonb,'"Infinity"'::jsonb,'"-Infinity"'::jsonb] loop
  perform late_test.fails(format('select public.record_manufactured_output(%L,%L,%L)',f,p||jsonb_build_object('scrap_kg',bad),gen_random_uuid()),'22023');
 end loop;
 perform late_test.fails(format('select public.record_manufactured_output(%L,%L,%L)',f,p||jsonb_build_object('scrap_kg','not a mass'),gen_random_uuid()),'22P02');
 perform late_test.fails(format('select public.record_manufactured_output(%L,%L,%L)',f,p||jsonb_build_object('input_quantity',11,'discarded_quantity',11),gen_random_uuid()),'output_input_quantity');
 perform late_test.fails(format('select public.record_manufactured_output(%L,%L,%L)',f,p||jsonb_build_object('discarded_quantity',9),gen_random_uuid()),'22023');
 perform late_test.fails(format('select public.record_manufactured_output(%L,%L,%L)',f,p||jsonb_build_object('input_lot',gen_random_uuid()),gen_random_uuid()),'output_input_required');
 perform late_test.ok((select count(*)=before_rows from public.production_entries where factory_id=f) and (select quantity_available=10 from public.unfinished_lots where id=(x->>'lot')::uuid),'invalid evidence leaves entry and source unchanged');
 perform set_config('request.jwt.claim.sub',x->>'viewer',false);
 perform late_test.fails(format('select public.record_manufactured_output(%L,%L,%L)',f,p,k),'42501');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 r:=public.record_manufactured_output(f,p,k);entry:=(r->>'entry_id')::uuid;
 perform late_test.ok(r->>'outcome'='COMMITTED' and r->>'recording_kind'='WIP_PROCESSING','zero-output recovery committed through existing V3');
 perform late_test.ok((select input_lot_id=(x->>'lot')::uuid and input_quantity=10 and effective_good=0 and effective_unfinished=0 and effective_scrap=10 and effective_scrap_kg=0.75 and original_scrap_kg=0.75 from public.production_entries where id=entry),'production units and measured Scrap KG remain separate');
 perform late_test.ok((select quantity_available=0 and warehouse_quantity=0 from public.unfinished_lots where id=(x->>'lot')::uuid),'all issued input consumed without negative balances');
 perform late_test.ok((select count(*)=1 from public.unfinished_movements where factory_id=f and lot_id=(x->>'lot')::uuid and kind='consumed' and quantity=-10),'one existing input consumption movement');
 select * into h from private.manufactured_outputs where factory_id=f and entry_id=entry;
 perform late_test.ok(h.quantity=0 and h.recorded_groups='[]'::jsonb,'immutable source marker has no fabricated usable groups');
 perform late_test.ok((select count(*)=1 from private.manufactured_output_events where output_id=h.id and operation='DECLARE' and request_id=k),'one immutable full-intent receipt');
 perform late_test.ok(not exists(select 1 from private.manufactured_output_events where output_id=h.id and operation='RECEIPT') and not exists(select 1 from public.finished_goods_movements where factory_id=f and entry_id=entry),'no Warehouse receipt or finished movement');
 perform late_test.ok(not exists(select 1 from public.unfinished_lots where factory_id=f and source_entry_id=entry),'no new unfinished lot');
 perform late_test.ok((select on_hand=90 and reserved=0 from public.finished_goods_balances where factory_id=f and product_id=(x->>'product')::uuid),'finished inventory stays ninety');
 perform late_test.ok(private.output_demand_received(f,origin)=90 and public.manufactured_completion_read(f)#>>'{work,0,demand_shortage}'='10','original finished demand remains ten short');
 perform late_test.ok((select demand_item_id=origin and quantity=10 from private.manufactured_completion_work where item_id=(w->>'item_id')::uuid),'original disposition retained without release or redirection');
 perform late_test.ok((select count(*)=1 from private.manufactured_completion_work where factory_id=f) and (select count(*)=2 from public.production_orders where factory_id=f),'no automatic replacement production is created');
 replay:=public.record_manufactured_output(f,p,k);
 perform late_test.ok(replay->>'entry_id'=entry::text and (replay->>'replayed')::boolean,'same UUID returns original immutable receipt');
 perform late_test.ok(public.manufactured_output_read(f,'status',k)->'receipt'=r,'status recovery returns original receipt');
 perform late_test.ok((select count(*)=1 and sum(effective_scrap_kg)=0.75 from public.production_entries where factory_id=f and order_id=(w->>'item_id')::uuid),'retry records measured Scrap once');
 perform late_test.fails(format('select public.record_manufactured_output(%L,%L,%L)',f,p||jsonb_build_object('scrap_kg',1),k),'40001');
 perform late_test.fails(format('select public.record_manufactured_output(%L,%L,%L)',f,p,gen_random_uuid()),'output_input_quantity');
 perform late_test.ok((select quantity_available=0 and warehouse_quantity=0 from public.unfinished_lots where id=(x->>'lot')::uuid),'rejected duplicate keeps zero physical balance');
 perform late_test.fails(format('select public.receive_manufactured_output(%L,%L,%L,1,%L)',f,h.id,jsonb_build_object('group_id',gen_random_uuid(),'quantity','1','location','No output','physical_confirmation',true),gen_random_uuid()),'output_quality_required');
 perform public.finish_product_item(f,(w->>'item_id')::uuid);
 perform late_test.ok((select status='completed' from public.production_orders where id=(w->>'item_id')::uuid) and private.output_demand_received(f,origin)=90,'failed manufacturing result can finish without satisfying demand');
 -- An unrelated factory's authenticated owner cannot read or mutate this source.
 y:=output4_test.context('Other factory');
 perform late_test.fails(format('select public.record_manufactured_output(%L,%L,%L)',f,p,gen_random_uuid()),'42501');
 perform late_test.fails(format('select public.manufactured_output_read(%L,''status'',%L)',f,k),'42501');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 perform late_test.ok((select count(*)=before_rows+1 from public.production_entries where factory_id=f),'denied cross-factory calls create no records');
 -- A partial failed attempt consumes only its four; the other six can still
 -- produce mixed usable output through the same protected job and source.
 x:=output4_test.context('Partial failed recovery');f:=(x->>'factory')::uuid;origin:=(x->>'item')::uuid;
 w:=output4_test.decision(x,'COMPLETE',10);y:=output4_test.start(x,w);
 insert into public.permission_packages(factory_id,name,created_by) values(f,'Local recovery recorder',(x->>'owner')::uuid) returning id into package;
 insert into public.permission_package_permissions(factory_id,package_id,module,action) values(f,package,'orders','view'),(f,package,'orders','edit');
 insert into public.member_permission_packages(factory_id,user_id,package_id) values(f,(x->>'worker')::uuid,package);
 perform set_config('request.jwt.claim.sub',x->>'worker',false);
 p:=output2_test.payload(y,0)||jsonb_build_object('input_lot',x->>'lot','input_quantity',4,'discarded_quantity',4,'scrap_kg',0.3);
 r:=public.record_manufactured_output(f,p,gen_random_uuid());
 perform late_test.ok((select created_by=(x->>'worker')::uuid from public.production_entries where id=(r->>'entry_id')::uuid),'effective package grants authorize actual recovery recording');
 perform late_test.ok((select quantity_available=6 and warehouse_quantity=0 from public.unfinished_lots where id=(x->>'lot')::uuid) and private.output_work_consumed(f,(w->>'item_id')::uuid)=4,'partial all-Scrap leaves six unprocessed, not consumed or reclassified');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 p:=output2_test.payload(y,3,3)||jsonb_build_object('input_lot',x->>'lot','input_quantity',6);
 p:=jsonb_set(p,'{output_groups}',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'quantity','3','missing_operations','[]'::jsonb),jsonb_build_object('id',gen_random_uuid(),'quantity','3','missing_operations',jsonb_build_array(x->>'step1'))));
 r:=public.record_manufactured_output(f,p,gen_random_uuid());
 perform late_test.ok(private.output_demand_received(f,origin)=90 and (select on_hand=90 from public.finished_goods_balances where factory_id=f),'later mixed result still awaits Quality and Warehouse');
 perform output4_test.receive(f,(r->>'entry_id')::uuid);
 perform late_test.ok(private.output_demand_received(f,origin)=93 and public.manufactured_completion_read(f)#>>'{work,0,demand_shortage}'='7','only three received finished satisfies demand, not failed or unfinished quantities');
 perform late_test.ok((select quantity_available=0 and warehouse_quantity=0 from public.unfinished_lots where id=(x->>'lot')::uuid) and (select sum(quantity_available)=3 and sum(warehouse_quantity)=3 from public.unfinished_lots where factory_id=f and id<>(x->>'lot')::uuid),'ten input equals four discarded plus three finished plus three unfinished');
 perform late_test.ok((select count(*)=2 and sum(input_quantity)=10 and sum(effective_scrap_kg)=0.3 from public.production_entries where factory_id=f and order_id=(w->>'item_id')::uuid),'partial attempts retain exact input and measured mass histories');
 -- Ordinary Scrap-only or new replacement work cannot use the narrow recovery exception.
 x:=output4_test.context('Ordinary zero denied');f:=(x->>'factory')::uuid;
 w:=output4_test.decision(x,'REPLACE',10);y:=output4_test.start(x,w);
 p:=output2_test.payload(y,0)||jsonb_build_object('scrap_kg',0.75,'discarded_quantity',10);
 perform late_test.fails(format('select public.record_manufactured_output(%L,%L,%L)',f,p,gen_random_uuid()),'output_conservation');
 perform late_test.ok(not exists(select 1 from public.production_entries where factory_id=f and order_id=(w->>'item_id')::uuid),'zero-output exception cannot enroll unrelated ordinary output');
 perform late_test.ok((public.manufactured_output_capability(f)->>'available')='false','shipped public capability stays FALSE');
end$$;
set constraints all immediate;
select count(*) assertions from late_test.checks;
rollback;
